请对以下 case 进行三维加权评分。

=== case_id ===
Case-26-group-buy-013

=== 用户原始指令 (query.txt) ===
黑色舞台感的拼单卡,氛围渐变带点冷色调,显示我的拼单列表,每单都能勾选加料,天气数据要展示,想直接跳到系统设置里把免打扰开起来。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "黑色舞台感的拼单卡,氛围渐变带点冷色调,显示我的拼单列表,每单都能勾选加料,天气数据要展示,想直接跳到系统设置里把免打扰开起来。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "intelligent_scene_entry"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询地区名称，用于辅助说明天气位置。",
            "sampleValue": "青浦"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "26°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "多云"
          }
        }
      },
      "groupBuy": {
        "summary": {
          "type": "string",
          "description": "我的拼单列表摘要。",
          "sampleValue": "2单待确认加料"
        },
        "orders": {
          "type": "array",
          "description": "我的拼单订单列表。",
          "sampleValue": [
            {
              "title": "黑椒鸡排团",
              "memberText": "2人成团",
              "addonLabel": "加料",
              "addonSelected": true
            },
            {
              "title": "冷萃咖啡团",
              "memberText": "差1人",
              "addonLabel": "加料",
              "addonSelected": false
            }
          ],
          "items": {
            "type": "object",
            "properties": {
              "title": {
                "type": "string",
                "description": "拼单订单名称。",
                "sampleValue": "黑椒鸡排团"
              },
              "memberText": {
                "type": "string",
                "description": "拼单人数或成团状态。",
                "sampleValue": "2人成团"
              },
              "addonLabel": {
                "type": "string",
                "description": "加料勾选项标签。",
                "sampleValue": "加料"
              },
              "addonSelected": {
                "type": "boolean",
                "description": "该拼单是否已勾选加料。",
                "sampleValue": true
              }
            }
          }
        }
      }
    },
    "state": {
      "loading": {
        "type": "boolean",
        "description": "卡片数据加载状态。",
        "sampleValue": false
      }
    }
  },
  "assetCandidates": []
}

